{
  "items": [
    {
      "name": "Polynomial.coeff_zero",
      "module_name": "Mathlib.Algebra.Polynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] (n : ℕ), Polynomial.coeff 0 n = 0"
    },
    {
      "name": "Polynomial.content_zero",
      "module_name": "Mathlib.RingTheory.Polynomial.Content",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : CommRing R] [inst_1 : NormalizedGCDMonoid R], Polynomial.content 0 = 0"
    },
    {
      "name": "Polynomial.sum_zero_index",
      "module_name": "Mathlib.Algebra.Polynomial.Basic",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] {S : Type u_1} [inst_1 : AddCommMonoid S] (f : ℕ → R → S), Polynomial.sum 0 f = 0"
    },
    {
      "name": "Poly.zero_apply",
      "module_name": "Mathlib.NumberTheory.Dioph",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} (x : α → ℕ), 0 x = 0"
    },
    {
      "name": "Polynomial.length_coeffList_eq_ite",
      "module_name": "Mathlib.Algebra.Polynomial.CoeffList",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} [inst : Semiring R] [inst_1 : DecidableEq R] (P : Polynomial R),\n  P.coeffList.length = if P = 0 then 0 else P.natDegree + 1"
    },
    {
      "name": "Polynomial.signVariations_zero",
      "module_name": "Mathlib.Algebra.Polynomial.RuleOfSigns",
      "kind": "theorem",
      "type": "∀ (R : Type u_1) [inst : Semiring R] [inst_1 : LinearOrder R], Polynomial.signVariations 0 = 0"
    },
    {
      "name": "Polynomial.leadingCoeff_zero",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Definitions",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R], Polynomial.leadingCoeff 0 = 0"
    },
    {
      "name": "Polynomial.leadingCoeff_eq_zero",
      "module_name": "Mathlib.Algebra.Polynomial.Degree.Definitions",
      "kind": "theorem",
      "type": "∀ {R : Type u} [inst : Semiring R] {p : Polynomial R}, p.leadingCoeff = 0 ↔ p = 0"
    }
  ]
}
